export type ReplyId = string | number | null;
export interface Failure { code: number; message: string; data?: unknown }
export interface Reply { version: "1"; id: ReplyId; result?: unknown; failure?: Failure }
export interface Call { id: ReplyId; method: string; args?: unknown[] }
export function describe(reply: Reply): string;
export class Dispatcher {
  dispatch(call: Call): Promise<Reply | null>;
  reject(id: ReplyId, message: string): Promise<Reply>;
  replyNow(call: Call): Reply;
}
